#include <stdio.h>

typedef enum { CLOSED, LISTEN, SYN_SENT, SYN_RCVD, ESTABLISHED, FIN_WAIT_1, FIN_WAIT_2, TIME_WAIT } State;

const char* state_name(State s) {
    switch(s) {
        case CLOSED: return "CLOSED";
        case SYN_SENT: return "SYN_SENT";
        case SYN_RCVD: return "SYN_RCVD";
        case ESTABLISHED: return "ESTABLISHED";
        default: return "OTHER";
    }
}

int main() {
    State s = CLOSED;
    printf("State: %s\n", state_name(s));
    // Client sends SYN
    s = SYN_SENT;
    printf("Send SYN -> %s\n", state_name(s));
    // Server receives SYN, sends SYN+ACK
    // Client receives SYN+ACK, sends ACK
    s = ESTABLISHED;
    printf("Receive SYN+ACK, send ACK -> %s\n", state_name(s));
    return 0;
}
